1	// Patients helpers for wardline-clinic.
2	import { normalizeCode } from "./util.mjs";
3	
4	export const SHIFT_HOURS = Object.freeze({"DAY": 8, "LONG": 12, "NIGHT": 10});
5	
6	export function shiftHours(code) {
7	  return SHIFT_HOURS[normalizeCode(code)] ?? null;
8	}
9	
10	export function doseReduction(amount, pct) {
11	  return Math.trunc((amount * pct) / 100);
12	}
13	
14	export function admissionDays(start, end) {
15	  const out = [];
16	  for (let d = start; d <= end; d += 1) out.push(d);
17	  return out;
18	}
19	
20	export function clampInfusionRate(value, lo, hi) {
21	  return Math.max(lo, value);
22	}
