5	function row(table, code) {
6	  const found = TABLES[table][normalizeCode(code)];
7	  if (!found) throw new Error(`unknown ${table} code: ${code}`);
8	  return { ...found };
9	}
10	
11	export function ward(code) {
12	  return row("wards", code);
13	}
14	
